const form = document.querySelector("#signup");
const errorList = document.querySelector("#errors");
const result = document.querySelector("#out");

// listen to the submit event: collect the errors in an array, then show them in the list
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const username = document.querySelector("#username").value.trim();
  const age = Number(document.querySelector("#age").value);
  const errors = [];
  if (username.length < 3 || username.length > 12) {
    errors.push("The username must be 3-12 letters.");
  }
  if (!Number.isInteger(age) || age < 10 || age > 99) {
    errors.push("The age must be a number between 10 and 99.");
  }
  errorList.innerHTML = "";
  for (const error of errors) {
    const li = document.createElement("li");
    li.textContent = error;
    errorList.append(li);
  }
  if (errors.length === 0) {
    result.textContent = `Signed up, ${username}!`;
    form.reset();
  } else {
    result.textContent = "";
  }
});

